<?php
require dirname(__DIR__).'/config.php';admin_required();$pdo=db();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$status=$_POST['status']??'';$allowed=['Pending','Confirmed','Processing','Out for Delivery','Delivered','Cancelled'];if(in_array($status,$allowed,true)){$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$status,$id]);flash('Order status updated.');}header('Location: orders.php');exit;}
$filters=[];$params=[];foreach(['order_code'=>'code','customer_name'=>'customer','status'=>'status'] as $col=>$key){$v=trim($_GET[$key]??'');if($v!==''){if($key==='status'){$filters[]="$col=?";$params[]=$v;}else{$filters[]="$col LIKE ?";$params[]='%'.$v.'%';}}}
$sql="SELECT * FROM orders".($filters?' WHERE '.implode(' AND ',$filters):'')." ORDER BY created_at DESC LIMIT 200";$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();$view=null;if(isset($_GET['view'])){$s=$pdo->prepare("SELECT * FROM orders WHERE id=?");$s->execute([(int)$_GET['view']]);$view=$s->fetch();if($view){$s=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$s->execute([$view['id']]);$view['items']=$s->fetchAll();}}
