><small>Payment</small><b><?=e($view['payment_method'])?></b></div><div><small>Total</small><b><?=money((float)$view['total'])?></b></div></div><h3>Items</h3><?php foreach($view['items'] as $it): ?><p><?=e($it['product_name'])?> · <?=e($it['unit'])?> × <?=(int)$it['quantity']?> <b class="float-right"><?=money((float)$it['price']*(int)$it['quantity'])?></b></p><?php endforeach; ?><form class="status-update" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$view['id']?>"><label>Update order status<select name="status"><?php foreach(['Pending','Confirmed','Processing','Out for Delivery','Delivered','Cancelled'] as $st): ?><option <?=($view['status']===$st?'selected':'')?>><?=e($st)?></option><?php endforeach; ?></select></label><button class="btn primary">Save status</button></form></div><?php endif; ?><div class="orders-layout"><section class="panel"><div class="panel-head"><div><h2>Order List</h2><p><?=count($orders)?> order(s) found</p></div></div><div class="table-scroll"><table><thead><tr><th>Order ID</th><th>Customer</th><th>Status</th><th>Total</th><th>Date Added</th><th>Date Modified</th><th>Action</th></tr></thead><tbody><?php if(!$orders): ?><tr><td colspan="7" class="empty-cell">No orders match these filters.</td></tr><?php endif; foreach($orders as $o): ?><tr><td><?=e($o['order_code'])?></td><td><?=e($o['customer_name'])?><small><?=e($o['phone'])?></small></td><td><span class="status status-<?=strtolower(str_replace(' ','-',$o['status']))?>"><?=e($o['status'])?></span></td><td><?=money((float)$o['total'])?></td><td><?=e(date('d/m/Y',strtotime($o['created_at'])))?></td><td><?=e(date('d/m/Y',strtotime($o['updated_at'])))?></td><td><a class="table-action" href="orders.php?view=<?=(int)$o['id']?>">◉ View</a></td></tr><?php endforeach; ?></tbody></table></div></section><aside class="panel filter-panel"><div class="panel-head"><h2>⚑ Filter</h2></div><form method="get"><label>Order ID<input name="code" placeholder="Order ID" value="<?=e($_GET['code']??'')?>"></label><label>Customer<input name="customer" placeholder="Customer" value="<?=e($_GET['customer']??'')?>"></label><label>Order Status<select name="status"><option value="">All statuses</option><?php foreach(['Pending','Confirmed','Processing','Out for Delivery','Delivered','Cancelled'] as $st): ?><option <?=((($_GET['status']??'')===$st)?'selected':'')?>><?=e($st)?></option><?php endforeach; ?></select></label><button class="btn primary full">⚑ Filter</button><a class="reset-filter" href="orders.php">Reset filters</a></form></aside></div></section></main></div><script src="../assets/js/admin.js"></script></body></html>